import{_ as n,c as i,o as r,as as t}from"./chunks/framework.DlmxyuuR.js";const c=JSON.parse('{"title":"Philips Hue","description":"","frontmatter":{},"headers":[],"relativePath":"de/user/leddevices/network/philipshue.md","filePath":"de/user/leddevices/network/philipshue.md","lastUpdated":1766332152000}'),a={name:"de/user/leddevices/network/philipshue.md"};function l(s,e,d,u,h,o){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="philips-hue" tabindex="-1">Philips Hue <a class="header-anchor" href="#philips-hue" aria-label="Permalink to &quot;Philips Hue&quot;">​</a></h1><p>Die bekannte <a href="https://www.philips-hue.com/de-de" target="_blank" rel="noreferrer">Philips Hue Bridge + Lampen</a> wird unterstützt. Wie kann man sie mit Hyperion konfigurieren? Schau selbst nach in der Web-Konfiguration</p><h2 id="entertainment-api" tabindex="-1">Entertainment API <a class="header-anchor" href="#entertainment-api" aria-label="Permalink to &quot;Entertainment API&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Warnung vor Anfällen bei Lichtempfindlichkeit</p><p>Bestimmte Personen fühlen sich möglicherweise unwohl, wenn sie schnellen Lichtblitzen/-mustern ausgesetzt sind. Bitte sehe sofort von der Verwendung des Unterhaltungsmodus ab, wenn du Unwohlsein verspürst oder irgendwelche dir bekannten Gesundheitszustände hast. Bitte informiere dich unter diesen Umständen bei einem Arzt. Stelle sicher, dass dein Unterhaltungsraum gut beleuchtet ist.</p><p>Hyperion kann nicht für vorhersehbare oder unvorhersehbare, negative oder schädliche Auswirkungen haftbar gemacht werden.</p></div><h3 id="anforderungen" tabindex="-1">Anforderungen <a class="header-anchor" href="#anforderungen" aria-label="Permalink to &quot;Anforderungen&quot;">​</a></h3><ul><li>Bevor du anfängst, benötigt die Entertainment-API mindestens eine Entertainment-Gruppe/Bereich mit mindestens einer zugewiesenen Lampe! Siehe: <a href="#entertainment-gruppen-bereiche">Entertainment-Gruppen / -Bereiche</a></li><li>Eine normale Hue-Gruppe, funktioniert NICHT mit der Hue Entertainment API!</li><li>Überprüfe die Option &quot;Use Hue Entertainment API&quot; und benutze den Philips Hue Entertainment-Assistenten bei der Web-Konfiguration zur Konfiguration ( zu finden unter LED-Hardware-Bereich)!</li><li>Die Entertainment-API benötigt zusätzlich eine Benutzer ID und einen passenden Clientkey. Schaue unter: <a href="#philips-hue-entertainment-wizard">Philips Hue Entertainment Wizard</a></li></ul><h3 id="philips-hue-entertainment-wizard" tabindex="-1">Philips Hue Entertainment Wizard <a class="header-anchor" href="#philips-hue-entertainment-wizard" aria-label="Permalink to &quot;Philips Hue Entertainment Wizard&quot;">​</a></h3><ul><li>Im Assistenten werden deine Hue-Bridges automatisch im lokalen netzwerk gefunden. Falls nicht, so versuche die IP-Adresse der Bridge einzugeben und klicke auf das &quot; Wiederholen&quot;-Symbol / die Schaltfläche neben dem IP-Eingabefeld.</li><li>Wenn nur die Benutzer ID bekannt ist oder man ganz von vorne anfängt, erstellt man mit dem Philips Hue Entertainment-Assistenten einen neuen Benutzer und ein Clientkey wird automatisch generiert.</li><li>Wurde auf der von dir verwendeten Bridge keine Entertainment-Gruppe / Bereich gefunden, schaltet der Assistent auf die klassische Version zurück und deaktiviert die Verwendung der Hue Entertainment API!</li><li>Benutzer ID, Clientkey und Entertainment-Gruppe / -Bereich vorhanden? Wählt die Unterhaltungsgruppe / den Bereich aus, die/den du verwenden möchtest, und stimmt die vorgewählten Bildschirmpositionen für jede Lampe ab.</li><li>Vergiss nicht, deine Änderungen zu speichern! 😉</li></ul><h3 id="bridge-anforderungen-einschrankungen" tabindex="-1">Bridge-Anforderungen / Einschränkungen <a class="header-anchor" href="#bridge-anforderungen-einschrankungen" aria-label="Permalink to &quot;Bridge-Anforderungen / Einschränkungen&quot;">​</a></h3><ul><li>Um die Philips Hue Entertainment API zu nutzen, muss die Bridge mindestens die API-Version 1.22 verwenden!</li><li>Auf einer Hue-Bridge kann immer nur eine Entertainment-Gruppe / ein Bereich aktiv sein!</li></ul><h3 id="nicht-originale-hue-bridge" tabindex="-1">Nicht originale Hue-Bridge <a class="header-anchor" href="#nicht-originale-hue-bridge" aria-label="Permalink to &quot;Nicht originale Hue-Bridge&quot;">​</a></h3><ul><li><a href="https://diyhue.org/" target="_blank" rel="noreferrer">diyHue</a> wird unterstützt. Bitte stell sicher, dass der Name Deine diyHue Bridge mit &quot;diyHue&quot; beginnt, damit Workarounds aktiviert werden, wenn diyHue sich nicht wie das Original verhält.</li><li>Wenn deine Bridge nicht gefunden wurde oder zwar gefunden wurde, aber nicht die, die du verwenden möchtest, gib die gewünschte Bridge-IP-Adresse manuell ein und klicke auf das Symbol / die Schaltfläche &quot;Wiederholen&quot; neben dem IP-Eingabefeld.</li></ul><h3 id="entertainment-gruppen-bereiche" tabindex="-1">Entertainment Gruppen / Bereiche <a class="header-anchor" href="#entertainment-gruppen-bereiche" aria-label="Permalink to &quot;Entertainment Gruppen / Bereiche&quot;">​</a></h3><ul><li>Entertainment-Gruppen / Bereiche können über die original Philips Hue-App oder in der Hue Essential-App (für diyHue) erstellt werden.</li><li>Stellt auch die rechte z-Achse (Bodenhöhe, TV-Höhe und Deckenhöhe) für jede Lampe innerhalb der Konfiguration der Entertainment-Gruppe / des Bereichs ein.Durch Antippen jeder Lampe ändert sich die Höhe und wird im Philips Hue Entertainment-Assistenten erkannt, um auch die richtige Bildschirmposition auszuwählen.</li><li>Du kannst bis zu 10 Philips Hue- oder Friends of Hue Leuchten pro Entertainment-Gruppe / Bereich anschließen.</li><li>Wenn eine Unterhaltungsgruppe / ein Unterhaltungsbereich mit der Unterhaltungs-API verwendet wird, kannst du keine der Lampen in der Unterhaltungsgruppe / dem Unterhaltungsbereich steuern, bis die Unterhaltungs-API stoppt!</li></ul><h3 id="konfigurations-tipps-tricks" tabindex="-1">Konfigurations Tipps &amp; Tricks <a class="header-anchor" href="#konfigurations-tipps-tricks" aria-label="Permalink to &quot;Konfigurations Tipps &amp; Tricks&quot;">​</a></h3><ul><li>Eine Farbkalibrierung ist nicht erforderlich, du kannst die Standardwerte beibehalten.</li><li>Um die aktive Entertainment-Gruppe / den Bereich von Hyperion aus zu aktivieren/deaktivieren, deaktiviere Hyperion oder nur die LED-Hardwarekomponente. Der vorherige Zustand der Lampe wird wiederhergestellt, wenn aktiviert.</li></ul><h2 id="klassische-philips-hue-nutzung-ohne-die-entertainment-api" tabindex="-1">Klassische Philips Hue-Nutzung ohne die Entertainment-API <a class="header-anchor" href="#klassische-philips-hue-nutzung-ohne-die-entertainment-api" aria-label="Permalink to &quot;Klassische Philips Hue-Nutzung ohne die Entertainment-API&quot;">​</a></h2><h3 id="erweiterte-einstellungen" tabindex="-1">Erweiterte Einstellungen <a class="header-anchor" href="#erweiterte-einstellungen" aria-label="Permalink to &quot;Erweiterte Einstellungen&quot;">​</a></h3><h4 id="signalerkennung" tabindex="-1">Signalerkennung <a class="header-anchor" href="#signalerkennung" aria-label="Permalink to &quot;Signalerkennung&quot;">​</a></h4><ul><li>Hyperion sendet kontinuierlich Farbinformationen an die Bridge. Deshalb kam die Signalerkennung ins Spiel.</li><li>Mit der Option <code>Signalerkennungs-Timeout bei Schwarz</code> kann man einstellen, wie lange alle Lampen auf Schwarz gesetzt werden bevor der vorherige Lampenzustand wiederhergestellt wird.</li><li>Einige Grabber liefern kein echtes Schwarz, sondern eher Dunkelgrau, so dass Schwarz = 0 nie vorkommt. Mit der Option <code>Signalerkennung Helligkeit Minimum</code> können wir die minimale Helligkeit einstellen, die als schwarz gilt. Der Bereich kann von 0 = 0% bis 1 = 100% eingestellt werden, z.B. 0,005 = 0,5%. Wenn 0 für deine Einstellung nicht funktioniert, erhöhe diesen Wert in 0,005 Schritten. Das ist wie bei den Schwellenwerten für USB Capture.</li></ul><h4 id="helligkeit-einstellungen-konnen-in-zukunftigen-versionen-entfernt-werden" tabindex="-1">Helligkeit <em>Einstellungen können in zukünftigen Versionen entfernt werden</em> <a class="header-anchor" href="#helligkeit-einstellungen-konnen-in-zukunftigen-versionen-entfernt-werden" aria-label="Permalink to &quot;Helligkeit *Einstellungen können in zukünftigen Versionen entfernt werden*&quot;">​</a></h4><ul><li>Setze / belasse <code>Helligkeitsfaktor</code> wieder auf 1 (Standard) - klassischer Fehler bei geringer Helligkeit ist behoben</li><li>Setze / belasse <code>Helligkeit Minimum</code> auf 0 (Standard) - Du kannst eine minimale Helligkeit einstellen, damit die Lampen nie aus sind</li><li>Setze / belasse <code>Helligkeit maximal</code> auf 1 (Voreinstellung) - Du kannst eine maximale Helligkeit einstellen, wenn du in hellen Szenen nicht den ganzen Raum aufleuchten lassen willst</li><li>Wertebereich für Helligkeit minimal / maximal sind: 0 = 0% bis 1 = 100%, z.B. 0,05 = 5% / 0,5 = 50%</li><li>Der Helligkeitsfaktor ist ein Multiplikator für die Eingangshelligkeit, d.h. z.B. 50% Eingangshelligkeit * Helligkeitsfaktor (z.B. 1,5) = neue 75% Helligkeit.</li><li><strong>Sei gewarnt</strong>: Wenn du den Helligkeitsfaktor / Minimum / Maximum auf einen anderen Wert als den Standardwert änderst, ändert sich auch die Farbwiedergabe!!! Z.B. wird Dunkel/Schwarz als tiefes Dunkelblau erscheinen, wenn du die minimale Helligkeit anhebst, weil die dunkelste Farbe innerhalb des Farbton-Licht-Systems ein dunkles Blau ist, denn Schwarz ist keine Farbe, sondern lediglich aus. <strong>UND</strong> du kannst das gesamte Entertainment-API-Erlebnis versäumen. 😉</li></ul><div class="warning custom-block"><p class="custom-block-title">Schnelle unkontrollierte Farben / Flackern</p><ul><li>Die Farbinformation für jede Lampe, hängt vom Eingangssignal deiner Aufnahmequelle, der definierten Bildschirmposition, die für die Lampe verwendet werden soll (wie jede andere LED-Konfiguration) und der verwendeten Aufnahmeframerate ab!</li><li>Eingangssignale mit Rauschen und anderen Bildstörungen können diesen Effekt des schnellen Farbwechsels/Flimmerns verursachen. Weitere Informationen, wie man das Problem reduzieren kann, findest du im nächsten Tipp:</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Aktiviere die Glättung in der Bildbearbeitung!</p><p>Dadurch kann das extrem schnelle Farb-/Flimmern sehr gut kontrolliert werden. Diese Werte funktionieren gut, aber entscheide selbst: Zeit: 80 - 120 ms Updatefrequenz: 35 - 40 Hz - höhere Werte führen wieder zu schnellerem Farbwechsel / Flackern Update-Verzögerung: 0 ms Kontinuierliche Ausgabe: nein - muss nicht sein, da die letzten Farbwerte in der jeweiligen Lampe gespeichert werden</p></div><h3 id="konfigurations-tipps-tricks-1" tabindex="-1">Konfigurations Tipps &amp; Tricks <a class="header-anchor" href="#konfigurations-tipps-tricks-1" aria-label="Permalink to &quot;Konfigurations Tipps &amp; Tricks&quot;">​</a></h3><ul><li>Verwende den Philips Hue-Assistenten bei der Webkonfiguration zur Konfiguration (verfügbar im Abschnitt &quot;LED-Hardware&quot;)!</li><li>Eine Farbkalibrierung ist nicht erforderlich, du kannst die Standardwerte beibehalten.</li><li>Wenn dir die Helligkeit zu niedrig ist und Hyperion bereits auf 100% steht, kannst du den Helligkeitsfaktor in der Webkonfiguration -&gt; LED-Hardware erhöhen.</li><li>Die Helligkeitskompensation beeinflusst die Helligkeit über verschiedene Farben hinweg (Einstellen in der Farbsektion)</li><li>Um die Bridge-Steuerung von Hyperion zu aktivieren/deaktivieren, deaktiviere entweder Hyperion oder nur die LED-Hardware-Komponente. Der vorherige Zustand der Lampe wird wiederhergestellt</li></ul>',26)])])}const m=n(a,[["render",l]]);export{c as __pageData,m as default};
